/** /developer/oidc 2 */
export async function _developer_oidc_2(): Promise<unknown> {
  const clientId: string = "mbx_live_…"
  const redirectUri: string = "https://app.example.com/auth/callback"
  const code: string = "…"
  const nonce: string = "…"
  const pkce = { codeVerifier: "…" }

  const tokens = await exchangeCode({
    clientId,
    clientSecret: process.env.MATCHBOX_CLIENT_SECRET ?? "",
    code,
    redirectUri,
    codeVerifier: pkce.codeVerifier,
  })
  const claims = await verifyIdToken(tokens.idToken ?? "", {
    clientId,
    nonce,
  })

  claims.sub // stable for your app
  claims.wallet_address // with the wallet scope
  return undefined
}

/** /developer/oidc 3 */
export async function _developer_oidc_3(): Promise<unknown> {
  const clientId: string = "mbx_live_…"
  const tokens = { accessToken: "…", refreshToken: "…" as string | undefined }

  const next = await refreshTokens({
    clientId,
    refreshToken: tokens.refreshToken ?? "",
  })
  const refreshed = await verifyIdToken(next.idToken ?? "", {
    clientId,
    nonce: null,
  })
  await revokeToken({
    clientId,
    token: next.refreshToken ?? "",
    tokenTypeHint: "refresh_token",
  })
  return undefined
}

